Translate("zhCN", "azeroth", {
	title = "艾泽拉斯",
	sections = {
		{
			title = "概述",
			text = [=[艾泽拉斯就是这个世界。它的海洋环抱着{link:eastern-kingdoms}东部王国{/link}、{link:kalimdor}卡利姆多{/link}和冰封的诺森德等大陆，还有无数岛屿。丛林、沙漠、森林和冰原在这片世界上相邻而列，在每一片土地上，旧时代的废墟都沉睡在新时代的城镇之下。这是一个有着众多民族和极其悠久记忆的世界。觊觎它的力量一次又一次地让它流血，而它一次又一次地挺了过来。]=],
		},
		{
			title = "起源",
			text = [=[最古老的史书说，艾泽拉斯是由泰坦塑造的，泰坦是一些如神明般的存在，在群星之间游历，为他们发现的世界带来秩序。他们来到艾泽拉斯时，这里被狂暴的{link:elements}元素{/link}和依附于世界的远古邪恶所统治。史书称这些邪恶为上古之神。泰坦打破了两者的力量。他们把元素领主束缚在一个与世界隔绝的国度里，并把上古之神囚禁在大地深处，因为若要杀死它们，就不得不伤及世界本身。随后，泰坦塑造了大地。他们的仆从筑起山脉，刻出{link:stranglethorn-vale}山谷{/link}，注满海洋。土灵，即由活石构成的生灵，被派去照管世界的深处。泰坦从巨龙中选出五条，赋予每一条一部分他们的力量。它们成为了守护巨龙，负责在造物者离去后守护艾泽拉斯。然后泰坦离开了，世界被留给了它自己的民族。]=],
		},
		{
			title = "世界诸纪元",
			text = [=[• {b}卡多雷帝国。{/b}在唯一一块大陆的中心，坐落着{link:well-of-eternity}永恒之井{/link}。{link:night-elves}暗夜精灵{/link}在{link:queen-azshara}艾萨拉女王{/link}的统治下，在它的岸边建立了一个奇迹般的帝国。
• {b}上古战争。{/b}上层精灵鲁莽的魔法引来了{link:burning-legion}燃烧军团{/link}的注视。在{link:war-of-the-ancients}上古战争{/link}中，暗夜精灵为世界的存亡而战，永恒之井的毁灭导致了{link:great-sundering}大分裂{/link}。唯一的大陆碎裂成了许多块。
• {b}年轻种族。{/b}在随后的纪元中，{link:trolls}巨魔{/link}帝国日渐衰落，{link:dwarves}矮人{/link}在山脉之下苏醒。{link:high-elves}高等精灵{/link}建立了{link:quel-thalas}奎尔萨拉斯{/link}，{link:humans}人类{/link}各{link:horde}部落{/link}联合为{link:arathor}阿拉索{/link}，投身于{link:troll-wars}巨魔战争{/link}。
• {b}部落的时代。{/b}{link:dark-portal}黑暗之门{/link}开启时，来自另一个世界的{link:orcs}兽人{/link}涌入了艾泽拉斯。随之而来的是{link:first-war}第一次战争{/link}、{link:second-war}第二次战争{/link}和{link:third-war}第三次战争{/link}，一次比一次可怕。]=],
		},
		{
			title = "同名之源",
			text = [=[艾泽拉斯这个名字也曾属于一个{link:humans}人类{/link}王国。定居在南方森林的{link:arathi-highlands}阿拉希{/link}流亡者把他们的新王国称为艾泽拉斯，它的首都是{link:stormwind-city}暴风城{/link}。久而久之，人们开始用城市的名字称呼这个王国，如今它是{link:kingdom-of-stormwind}暴风王国{/link}。{link:first-war}第一次战争{/link}的老兵有时仍会说起“艾泽拉斯”，指的只是他们失去的那个王国。]=],
		},
		{
			title = "当今",
			text = [=[{link:third-war}第三次战争{/link}以{link:archimonde}阿克蒙德{/link}在{link:nordrassil}诺达希尔{/link}脚下的陨落而告终，但它并没有带来和平。{link:scourge}天灾军团{/link}占据着{link:lordaeron}洛丹伦{/link}的北部。{link:burning-legion}燃烧军团{/link}的仆从仍在{link:kalimdor}卡利姆多{/link}的森林中出没。曾在{link:mount-hyjal}海加尔山{/link}上并肩作战的{link:alliance}联盟{/link}和{link:horde}部落{/link}，如今隔着{link:the-barrens}贫瘠之地{/link}和{link:ashenvale}灰谷{/link}的森林彼此猜疑地对望。在{link:blackrock-mountain}黑石山{/link}下，{link:dark-iron-dwarves}黑铁矮人{/link}效忠于一位活火之王。艾泽拉斯挺过了迄今在它身上发生过的每一场战争。但没有哪位史官敢说它不会陨落。]=],
		},
	},
})

Translate("zhCN", "eastern-kingdoms", {
	title = "东部王国",
	sections = {
		{
			title = "概述",
			text = [=[东部王国从{link:alterac-mountains}奥特兰克山脉{/link}的冰峰一直延伸到{link:stranglethorn-vale}荆棘谷{/link}的丛林。这里是{link:humans}人类{/link}、{link:dwarves}矮人{/link}和{link:gnomes}侏儒{/link}的故乡，也是{link:quel-thalas}奎尔萨拉斯{/link}的{link:high-elves}高等精灵{/link}的故乡。古老而伟大的人类王国曾矗立于此，{link:horde}部落{/link}也在这里向{link:azeroth}艾泽拉斯{/link}发动了它的第一场战争。这片土地留着此后每一场战争的伤痕。曾经骄傲的王国沦为废墟，北方已成亡者之地。]=],
		},
		{
			title = "起源",
			text = [=[在{link:great-sundering}大分裂{/link}之前，这些土地是唯一一块大陆的东部边陲。{link:well-of-eternity}永恒之井{/link}被摧毁时，海水奔涌而入，将它们撕裂开来。剩下的是一片早已古老的土地。泰坦在这里留下了他们的造物，其中包括多岩的{link:badlands}废土{/link}中的{link:uldaman}奥达曼宝库{/link}。他们的土灵仆从在宝库的大厅中沉睡。在漫长的岁月里，土灵发生了变化。他们的血肉变得柔软，寿命变得短暂，卡兹莫丹的{link:dwarves}矮人{/link}便由他们而来。据记载，另一个由泰坦锻造的种族孕育了{link:gnomes}侏儒{/link}。{link:trolls}巨魔{/link}在这片土地上的历史还要更加古老。阿曼尼统治着北方的森林，古拉巴什占据着南方的丛林。]=],
		},
		{
			title = "历史",
			text = [=[• {b}精灵的到来。{/b}被逐出{link:kalimdor}卡利姆多{/link}的上层精灵渡过大海，在北方森林中建立了{link:quel-thalas}奎尔萨拉斯{/link}，而那片土地被阿曼尼视为己有。
• {b}阿拉索。{/b}北方的{link:humans}人类{/link}{link:horde}部落{/link}由{link:thoradin}索拉丁{/link}统一，他建起了{link:stromgarde-keep}斯托姆{/link}城。他的军队与精灵一道，在{link:troll-wars}巨魔战争{/link}中击溃了阿曼尼。作为回报，精灵把魔法之道传授给人类，这便是{link:arathor}阿拉索{/link}的魔法，后来这一脉的法师建立了达拉然。
• {b}七大王国。{/b}久而久之，阿拉索{link:great-sundering}分裂{/link}了。{link:lordaeron}洛丹伦{/link}、{link:gilneas}吉尔尼斯{/link}、{link:kul-tiras}库尔提拉斯{/link}、{link:alterac-mountains}奥特兰克{/link}、{link:dalaran}达拉然{/link}和激流堡等王国在北方崛起。在南方，{link:arathi-highlands}阿拉希{/link}流亡者建立了后来成为{link:kingdom-of-stormwind}暴风王国{/link}的国度。
• {b}三锤之战。{/b}在山脉之下，{link:kingdom-of-ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}分裂为铜须、蛮锤和{link:dark-iron-dwarves}黑铁{/link}三个氏族。他们的战争在烈火中结束。黑铁的巫师领主{link:ruins-of-thaurissan}索瑞森{/link}召唤了炎魔之王{link:ragnar-thunderbrew}拉格纳{/link}罗斯，这次召唤造就了{link:blackrock-mountain}黑石山{/link}，并烧焦了周围的土地。
• {b}部落之战。{/b}{link:dark-portal}黑暗之门{/link}在南方开启。{link:stormwind-city}暴风城{/link}在{link:first-war}第一次战争{/link}中陷落。洛丹伦的{link:alliance}联盟{/link}在{link:second-war}第二次战争{/link}中击退了部落。随后到来的是亡灵瘟疫、{link:culling-of-stratholme}斯坦索姆的净化{/link}和{link:fall-of-lordaeron}洛丹伦的陷落{/link}。]=],
		},
		{
			title = "当今",
			text = [=[{link:stormwind-city}暴风城{/link}已经重新崛起，但它的国王下落不明，它的摄政王{link:bolvar-fordragon}伯瓦尔·弗塔根{/link}掌管着一个捉襟见肘的王国。{link:magni-bronzebeard}麦格尼·铜须{/link}统治着{link:ironforge}铁炉堡{/link}，那里也收留了{link:gnomes}侏儒{/link}，因为{link:gnomeregan}诺莫瑞根{/link}已毁于其自身的灾难。在{link:thandol-span}萨多尔大桥{/link}以北，伟大的{link:lordaeron}洛丹伦{/link}王国已不复存在。{link:scourge}天灾军团{/link}占据着瘟疫之地。{link:scarlet-crusade}血色十字军{/link}的狂热者以火焰和猜疑与之作战。在旧都的废墟中，{link:forsaken}被遗忘者{/link}在地下建起了家园。在{link:blackrock-mountain}黑石山{/link}中，{link:dark-iron-dwarves}黑铁矮人{/link}与{link:orcs}兽人{/link}互相厮杀。而在南方，{link:dark-portal}黑暗之门{/link}静静地矗立在{link:blasted-lands}诅咒之地{/link}。]=],
		},
	},
})

Translate("zhCN", "kalimdor", {
	title = "卡利姆多",
	sections = {
		{
			title = "概述",
			text = [=[卡利姆多位于{link:eastern-kingdoms}东部王国{/link}以西的大海彼岸。这是一片有着古老森林与红色峡谷、辽阔{link:burning-steppes}平原{/link}与炽热沙漠的土地。它是{link:night-elves}暗夜精灵{/link}和{link:tauren}牛头人{/link}的故乡，也是世界古老的心脏。今天的卡利姆多只是{link:great-sundering}大分裂{/link}后幸存下来的部分。在那场灾变之前，唯一的一块大陆承载着{link:azeroth}艾泽拉斯{/link}几乎所有的土地，而它中心的湖泊就是{link:well-of-eternity}永恒之井{/link}。]=],
		},
		{
			title = "起源",
			text = [=[卡利姆多最古老的民族是{link:trolls}巨魔{/link}，他们的帝国遍布这片原始大陆。一支定居在{link:well-of-eternity}永恒之井{/link}旁的巨魔{link:horde}部落{/link}，经过许多世代，被井的力量所改变。他们成为了{link:night-elves}暗夜精灵{/link}，并为这片土地取名为卡利姆多。他们在{link:queen-azshara}艾萨拉女王{/link}的统治下，在井畔建起了卡多雷帝国的城市。他们对{link:arcane-magic}奥术魔法{/link}的追求把{link:burning-legion}燃烧军团{/link}引入了这个世界。在{link:war-of-the-ancients}上古战争{/link}中，永恒之井被摧毁，大陆随之碎裂。海水涌入了这道伤口，大漩涡从此便在那里翻腾不息。幸存者在{link:mount-hyjal}海加尔山{/link}的山坡上种下了{link:nordrassil}诺达希尔{/link}，一万年来，暗夜精灵一直在隐秘中守望着他们的森林。]=],
		},
		{
			title = "历史",
			text = [=[• {b}漫长的守望。{/b}在{link:malfurion-stormrage}玛法里奥·怒风{/link}和{link:tyrande-whisperwind}泰兰德·语风{/link}的领导下，{link:night-elves}暗夜精灵{/link}摒弃了{link:arcane-magic}奥术魔法{/link}。德鲁伊们沉睡在{link:emerald-dream}翡翠梦境{/link}中，{link:sentinels}哨兵{/link}们独自守卫着森林。
• {b}荒野的民族。{/b}{link:tauren}牛头人{/link}在{link:burning-steppes}平原{/link}上漂泊。世世代代，他们受到南方的{link:centaurs}半人马{/link}、{link:the-barrens}贫瘠之地{/link}的{link:quilboar}野猪人{/link}、悬崖上的{link:harpies}鹰身人{/link}和森林中的{link:furbolgs}熊怪{/link}的侵扰。
• {b}第三次战争。{/b}在{link:third-war}第三次战争{/link}中，{link:thrall}萨尔{/link}率领的新的{link:horde}部落{/link}渡过了大海，{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}的{link:humans}人类{/link}也是如此。{link:burning-legion}燃烧军团{/link}紧随其后。{link:orcs}兽人{/link}、人类和暗夜精灵，曾经的陌生人与仇敌，在{link:battle-of-mount-hyjal}海加尔山之战{/link}中并肩作战，{link:archimonde}阿克蒙德{/link}在那里被消灭。]=],
		},
		{
			title = "当今",
			text = [=[卡利姆多不再是一片隐秘的土地。{link:night-elves}暗夜精灵{/link}种下了一棵新的大树{link:teldrassil}泰达希尔{/link}，树上的城市{link:darnassus}达纳苏斯{/link}俯瞰着北方的大海。{link:orcs}兽人{/link}建立了{link:durotar}杜隆塔尔{/link}和{link:orgrimmar}奥格瑞玛{/link}城，{link:cairne-bloodhoof}凯恩·血蹄{/link}的{link:tauren}牛头人{/link}则在{link:mulgore}莫高雷{/link}的{link:thunder-bluff}雷霆崖{/link}安了家。{link:darkspear-trolls}暗矛巨魔{/link}住在兽人身旁。{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}据守着{link:dustwallow-marsh}尘泥沼泽{/link}的{link:theramore-isle}塞拉摩{/link}。然而{link:mount-hyjal}海加尔山{/link}的和平正在瓦解。兽人伐木工砍伐{link:ashenvale}灰谷{/link}的树木，{link:sentinels}哨兵{/link}们以箭矢回应。{link:steamwheedle-cartel}热砂港{/link}和{link:venture-company}风险投资公司{/link}的地精沿着海岸经商和劫掠。{link:felwood}费伍德森林{/link}的森林仍带着{link:burning-legion}燃烧军团{/link}的污染，更古老的谜团沉睡在南方的沙漠中。]=],
		},
	},
})

Translate("zhCN", "war-of-the-ancients", {
	title = "上古战争",
	sections = {
		{
			title = "概述",
			text = [=[上古战争是{link:burning-legion}燃烧军团{/link}对{link:azeroth}艾泽拉斯{/link}的第一次入侵。它发生在{link:dark-portal}黑暗之门{/link}开启前约一万年，终结了{link:night-elves}卡多雷{/link}帝国。它的最后时刻带来了{link:great-sundering}大分裂{/link}，使世界破碎。]=],
		},
		{
			title = "起源",
			text = [=[{link:night-elves}暗夜精灵{/link}宫廷中的上层精灵越来越深地汲取{link:well-of-eternity}永恒之井{/link}的力量。他们的魔法被世界之外的{link:sargeras}萨格拉斯{/link}感知到了，他是领导{link:burning-legion}燃烧军团{/link}的堕落泰坦。他向{link:queen-azshara}艾萨拉女王{/link}低语，而她相信了他。{link:azshara}艾萨拉{/link}和她的上层精灵致力于在永恒之井中打开一道传送门，好让萨格拉斯和他的恶魔进入{link:azeroth}艾泽拉斯{/link}。]=],
		},
		{
			title = "历史",
			text = [=[第一批恶魔在{link:archimonde}阿克蒙德{/link}和{link:mannoroth}玛诺洛斯{/link}的率领下穿过传送门，屠杀了挡在他们路上的{link:night-elves}暗夜精灵{/link}。一支反抗力量起来对抗他们和女王。领导它的是半神{link:cenarius}塞纳留斯{/link}的年轻学生{link:malfurion-stormrage}玛法里奥·怒风{/link}，与他一起的还有女祭司{link:tyrande-whisperwind}泰兰德·语风{/link}和玛法里奥的孪生兄弟{link:illidan-stormrage}伊利丹·怒风{/link}。荒野的半神和各龙族也加入了战斗。当巨龙中的大地守护者背叛了他的同类时，这场战争几乎失败。他就是后来成为{link:deathwing}死亡之翼{/link}的那位守护巨龙。最终，守卫者们攻入上层精灵的宫殿，在{link:sargeras}萨格拉斯{/link}试图穿过传送门时打破了他们的法术。传送门崩塌了，{link:well-of-eternity}永恒之井{/link}也随之自我撕裂。]=],
		},
		{
			title = "意义",
			text = [=[这场战争让{link:night-elves}暗夜精灵{/link}认识到，{link:arcane-magic}奥术魔法{/link}几乎毁灭了世界。他们摒弃了它，转向德鲁伊之道和对艾露恩的崇拜，并开始了他们漫长的守望。它也让{link:illidan-stormrage}伊利丹{/link}在族人眼中成了叛徒，因为他曾秘密地与上层精灵合作，事后他还在{link:mount-hyjal}海加尔山{/link}顶造出了一口新的{link:well-of-eternity}永恒之井{/link}。]=],
		},
	},
})

Translate("zhCN", "great-sundering", {
	title = "大分裂",
	aliases = { "分裂" },
	sections = {
		{
			title = "概述",
			text = [=[大分裂是终结{link:war-of-the-ancients}上古战争{/link}的那场灾变。{link:well-of-eternity}永恒之井{/link}崩塌时，远古世界唯一的大陆碎裂了，海水奔涌而入，填满了这道伤口。{link:azeroth}艾泽拉斯{/link}的面貌从此永远改变。]=],
		},
		{
			title = "历史",
			text = [=[上层精灵的传送门在战争的最后时刻被瓦解。被注入了超出其承受能力之力量的{link:well-of-eternity}永恒之井{/link}向内崩塌。爆炸撕裂了大陆的心脏。{link:night-elves}卡多雷{/link}帝国的大部分地区，连同它光辉的首都辛艾萨莉，都被大海吞没。{link:queen-azshara}艾萨拉女王{/link}和她的许多上层精灵被卷入了海浪之下。在永恒之井原来所在的地方，海水开始旋转，被称为大漩涡的巨大风暴就此诞生。它从未停息。]=],
		},
		{
			title = "此后的世界",
			text = [=[古老大陆只剩下一些碎片露出水面。其中最大的几块成为了西方的{link:kalimdor}卡利姆多{/link}和东方的{link:eastern-kingdoms}东部王国{/link}，而冰封的诺森德位于北方。幸存的{link:night-elves}暗夜精灵{/link}聚集在{link:mount-hyjal}海加尔山{/link}的山坡上。他们在那里发现，{link:illidan-stormrage}伊利丹·怒风{/link}带走了几瓶{link:well-of-eternity}永恒之井{/link}的井水，并把它们倒进了一座山中湖泊，造出了第二口永恒之井。为了守护它，守护巨龙在井水之上种下了{link:nordrassil}诺达希尔{/link}。]=],
		},
		{
			title = "意义",
			text = [=[对{link:night-elves}暗夜精灵{/link}来说，大分裂证明了{link:arcane-magic}奥术魔法{/link}的代价。对世界来说，它意味着一万年的分离。东方和西方的民族彼此遗忘，直到{link:third-war}第三次战争{/link}再次把他们聚到一起。据说如今出没于海岸的{link:naga}纳迦{/link}就是溺水的上层精灵，已经变得面目全非。]=],
		},
	},
})

Translate("zhCN", "troll-wars", {
	title = "巨魔战争",
	sections = {
		{
			title = "概述",
			text = [=[巨魔战争是阿曼尼{link:trolls}巨魔{/link}与{link:humans}人类{/link}和{link:high-elves}高等精灵{/link}的年轻王国之间的战争，发生在{link:dark-portal}黑暗之门{/link}开启前约两千八百年。精灵与人类的{link:alliance}联盟{/link}以及第一批人类法师都由此而来。]=],
		},
		{
			title = "起源",
			text = [=[被逐出{link:kalimdor}卡利姆多{/link}的上层精灵在{link:eastern-kingdoms}东部王国{/link}北方的森林中建立了{link:quel-thalas}奎尔萨拉斯{/link}。那些森林曾属于阿曼尼，{link:trolls}巨魔{/link}从未原谅这次掠夺。数千年来，他们一直与精灵交战。最后，他们集结了一支大军，也许还有他们的古拉巴什亲族加入，出发去彻底摧毁奎尔萨拉斯。]=],
		},
		{
			title = "历史",
			text = [=[在同一个时代，{link:arathi-highlands}阿拉希{/link}部族的{link:thoradin}索拉丁{/link}已把北方的{link:humans}人类{/link}{link:horde}部落{/link}统一为{link:arathor}阿拉索{/link}王国，首都设在{link:stromgarde-keep}斯托姆{/link}。{link:quel-thalas}奎尔萨拉斯{/link}的精灵在绝望中向他派出了使者。索拉丁同意援助他们，条件是精灵要把魔法传授给他的人民。精灵挑选了一百名有魔法天赋的人类，只教给他们必需的东西。联军在{link:alterac-mountains}奥特兰克山脉{/link}南部与阿曼尼大军相遇。人类法师和精灵魔导师向{link:trolls}巨魔{/link}降下烈火，火焰烧掉了巨魔原本能够愈合的伤口。阿曼尼溃散而逃，他们的帝国再也没有恢复元气。]=],
		},
		{
			title = "意义",
			text = [=[出于感激，{link:quel-thalas}奎尔萨拉斯{/link}的精灵向{link:thoradin}索拉丁{/link}的血脉立下了友谊的誓言。这个誓言日后将把他们带入{link:second-war}第二次战争{/link}。传授给{link:humans}人类{/link}的魔法远远传播到了最初那一百人之外。它孕育了{link:dalaran}达拉然{/link}和{link:kirin-tor}肯瑞托{/link}，也再一次引起了{link:burning-legion}燃烧军团{/link}的注意。]=],
		},
	},
})

Translate("zhCN", "first-war", {
	title = "第一次战争",
	sections = {
		{
			title = "概述",
			text = [=[第一次战争是{link:orcs}兽人{/link}{link:horde}部落{/link}对{link:humans}人类{/link}王国{link:azeroth}艾泽拉斯{/link}的入侵。它始于{link:dark-portal}黑暗之门{/link}在黑色{link:swamp-of-sorrows}沼泽{/link}开启之时，终于{link:stormwind-city}暴风城{/link}的陷落。这是兽人与人类之间的第一场战争，也是那个此后一直塑造着世界的时代的开端。]=],
		},
		{
			title = "起源",
			text = [=[在他们的世界德拉诺上，{link:orcs}兽人{/link}被恶魔领主{link:kil-jaeden}基尔加丹{/link}通过术士{link:gul-dan}古尔丹{/link}和他的{link:shadow-council}暗影议会{/link}腐化了。他们的家园正在死去。在{link:azeroth}艾泽拉斯{/link}，{link:tirisfal-glades}提瑞斯法{/link}守护者{link:medivh}麦迪文{/link}早已被{link:sargeras}萨格拉斯{/link}的灵魂附身。麦迪文与古尔丹合作，帮助打开了两个世界之间的通道。]=],
		},
		{
			title = "历史",
			text = [=[最初只有少量{link:orcs}兽人{/link}穿过通道，袭击黑色{link:swamp-of-sorrows}沼泽{/link}。随后传送门扩大了，{link:horde}部落{/link}在大酋长黑手的率领下大举入侵。国王{link:llane-wrynn}莱恩·乌瑞恩{/link}和他的勇士{link:anduin-lothar}安度因·洛萨{/link}在南方王国与他们鏖战多年。部落焚烧了{link:elwynn-forest}艾尔文{/link}的农庄、{link:duskwood}暮色森林{/link}的树林和{link:northshire-abbey}北郡修道院{/link}。洛萨和年轻的法师{link:khadgar}卡德加{/link}终于在{link:karazhan}卡拉赞{/link}的高塔中杀死了疯狂的守护者。但对王国来说已经太迟了。半兽人{link:garona}迦罗娜{/link}在国王{link:raene-wolfrunner}莱恩{/link}自己的城堡中杀死了他，{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}从黑手手中夺取了部落，{link:stormwind-city}暴风城{/link}遭到洗劫。]=],
		},
		{
			title = "意义",
			text = [=[{link:anduin-lothar}洛萨{/link}带领幸存者向北渡海前往{link:lordaeron}洛丹伦{/link}，随行的还有{link:raene-wolfrunner}莱恩{/link}的儿子{link:varian-wrynn}瓦里安{/link}。他们的警告促使国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}召集{link:alliance}联盟{/link}，为{link:second-war}第二次战争{/link}做准备。]=],
		},
	},
})

Translate("zhCN", "second-war", {
	title = "第二次战争",
	sections = {
		{
			title = "概述",
			text = [=[第二次战争是{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}率领的{link:horde}部落{/link}与{link:lordaeron}洛丹伦{/link}{link:alliance}联盟{/link}之间的战争。部落向北进军，要征服在{link:first-war}第一次战争{/link}中幸存下来的{link:humans}人类{/link}王国。它在{link:blackrock-mountain}黑石{/link}塔被击溃。]=],
		},
		{
			title = "历史",
			text = [=[{link:lordaeron}洛丹伦{/link}国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}把各{link:humans}人类{/link}王国召集成一个{link:alliance}联盟{/link}，由{link:anduin-lothar}安度因·洛萨{/link}担任统帅。{link:kingdom-of-ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}和{link:gnomes}侏儒{/link}加入了他们。{link:quel-thalas}奎尔萨拉斯{/link}的精灵也加入了，因为他们受到曾向{link:thoradin}索拉丁{/link}血脉立下的古老誓言的约束，而洛萨正是这一血脉的最后继承人。{link:horde}部落{/link}以比以前更强大的力量到来。毁灭之锤把{link:ogres}食人魔{/link}和祖尔{link:ginro-hearthkindle}金{/link}的阿曼尼{link:trolls}巨魔{/link}拉到了自己一边。{link:dragonmaw-clan}龙喉氏族{/link}奴役了红龙军团，骑着它的巨龙投入战斗。{link:gul-dan}古尔丹{/link}用阵亡的人类骑士的尸体造出了死亡骑士。部落攻陷了卡兹莫丹，焚烧了奎尔萨拉斯的边境。{link:alterac-mountains}奥特兰克{/link}的佩{link:farmer-ray}雷{/link}诺德领主把联盟出卖给了{link:orcs}兽人{/link}。部落一直打到了洛丹伦首都的城墙下。]=],
		},
		{
			title = "战争的转折",
			text = [=[在战争最激烈的时候，{link:gul-dan}古尔丹{/link}抛弃了毁灭之锤。他带着追随者扬帆而去，寻找{link:sargeras}萨格拉斯{/link}之墓，{link:horde}部落{/link}被迫回师去惩罚他。{link:alliance}联盟{/link}抓住了这个时机。它把部落向南驱赶到{link:blackrock-mountain}黑石{/link}塔。{link:anduin-lothar}洛萨{/link}在那里死于毁灭之锤之手。他的副官{link:turalyon}图拉扬{/link}接过了他的旗帜，在{link:burning-steppes}燃烧平原{/link}击溃了部落。]=],
		},
		{
			title = "意义",
			text = [=[幸存的{link:orcs}兽人{/link}被赶进了{link:internment-camps}收容所{/link}。{link:dark-portal}黑暗之门{/link}被摧毁。{link:alliance}联盟{/link}胜利了，但这场胜利代价高昂。它的各个王国很快就为收容所的开销争吵不休，{link:gilneas}吉尔尼斯{/link}和{link:stromgarde-keep}激流堡{/link}退出了联盟。]=],
		},
	},
})

Translate("zhCN", "third-war", {
	title = "第三次战争",
	sections = {
		{
			title = "概述",
			text = [=[第三次战争是{link:burning-legion}燃烧军团{/link}对{link:azeroth}艾泽拉斯{/link}的第二次入侵。它始于{link:lordaeron}洛丹伦{/link}的一场亡灵瘟疫，终于{link:kalimdor}卡利姆多{/link}{link:archimonde}阿克蒙德{/link}的毁灭。它让{link:humans}人类{/link}失去了他们最伟大的王国，让{link:night-elves}暗夜精灵{/link}失去了他们的永生。]=],
		},
		{
			title = "起源",
			text = [=[{link:second-war}第二次战争{/link}之后，恶魔{link:kil-jaeden}基尔加丹{/link}把{link:orcs}兽人{/link}萨满{link:ner-zhul}耐奥祖{/link}的灵魂束缚在诺森德的一座冰封牢笼中，使他成为巫妖王。巫妖王通过死灵法师{link:kel-thuzad}克尔苏加德{/link}和他的{link:cult-of-the-damned}诅咒教派{/link}，在{link:lordaeron}洛丹伦{/link}的村庄中散布瘟疫。瘟疫的受害者以亡灵{link:scourge}天灾军团{/link}的身份复活。与此同时，年轻的兽人{link:thrall}萨尔{/link}把他的族人从{link:internment-camps}收容所{/link}中解放出来，锻造了一个新的{link:horde}部落{/link}。]=],
		},
		{
			title = "历史",
			text = [=[一位神秘的先知警告东方的国王们向西渡海逃离。国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}不肯听从，但{link:thrall}萨尔{/link}和{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}响应了召唤。那位先知就是从死亡中归来的{link:medivh}麦迪文{/link}。在{link:lordaeron}洛丹伦{/link}，{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子追查瘟疫的源头。在{link:culling-of-stratholme}斯坦索姆的净化{/link}之后，他航行到诺森德，拿起了被诅咒的利刃霜之哀伤。他以死亡骑士的身份归来，造成了{link:fall-of-lordaeron}洛丹伦的陷落{/link}。{link:scourge}天灾军团{/link}在{link:quel-thalas}奎尔萨拉斯{/link}的太阳之井复活了{link:kel-thuzad}克尔苏加德{/link}，{link:archimonde}阿克蒙德{/link}在{link:dalaran}达拉然{/link}进入世界并将它摧毁。随后{link:burning-legion}燃烧军团{/link}追随{link:horde}部落{/link}和{link:humans}人类{/link}来到{link:kalimdor}卡利姆多{/link}。在那里，{link:night-elves}暗夜精灵{/link}从他们的守望中起身。]=],
		},
		{
			title = "意义",
			text = [=[{link:orcs}兽人{/link}、{link:humans}人类{/link}和{link:night-elves}暗夜精灵{/link}终于携手合作。在{link:battle-of-mount-hyjal}海加尔山之战{/link}中，他们消灭了{link:archimonde}阿克蒙德{/link}。这场战争带来了新的{link:horde}部落{/link}在{link:kalimdor}卡利姆多{/link}的土地、{link:theramore-isle}塞拉摩城{/link}和{link:forsaken}被遗忘者{/link}。它的伤口至今仍未愈合。]=],
		},
	},
})

Translate("zhCN", "battle-of-mount-hyjal", {
	title = "海加尔山之战",
	aliases = { "海加尔之战" },
	sections = {
		{
			title = "概述",
			text = [=[海加尔山之战是{link:third-war}第三次战争{/link}的最后一战。在圣山的山坡上，{link:orcs}兽人{/link}、{link:humans}人类{/link}和{link:night-elves}暗夜精灵{/link}并肩对抗{link:burning-legion}燃烧军团{/link}。恶魔领主{link:archimonde}阿克蒙德{/link}在{link:nordrassil}诺达希尔{/link}的树根下被消灭。]=],
		},
		{
			title = "起源",
			text = [=[{link:burning-legion}燃烧军团{/link}是为世界之树而来到{link:kalimdor}卡利姆多{/link}的。{link:archimonde}阿克蒙德{/link}企图汲取树根下第二口{link:well-of-eternity}永恒之井{/link}的力量，并借此吞噬世界。{link:scourge}天灾军团{/link}在他前面进军。{link:tyrande-whisperwind}泰兰德·语风{/link}和{link:malfurion-stormrage}玛法里奥·怒风{/link}的{link:night-elves}暗夜精灵{/link}无法独自抵挡。{link:medivh}麦迪文{/link}把他们的领袖与{link:horde}部落{/link}的{link:thrall}萨尔{/link}和{link:humans}人类{/link}的{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}召集到一起。他告诉他们，只有团结起来才能生存。]=],
		},
		{
			title = "历史",
			text = [=[{link:malfurion-stormrage}玛法里奥{/link}制定了计划。{link:humans}人类{/link}在较低的山坡上坚守，{link:orcs}兽人{/link}在更高处，每一方都尽可能久地坚持，然后后撤。在他们作战的同时，玛法里奥在山顶布下了一个陷阱。{link:archimonde}阿克蒙德{/link}依次突破了每一道防线，最终抵达了大树。当他攀上{link:nordrassil}诺达希尔{/link}时，玛法里奥吹响了{link:cenarius}塞纳留斯{/link}之角。{link:night-elves}暗夜精灵{/link}祖先的灵魂化作无数小精灵，蜂拥扑向恶魔。它们的力量和世界之树的力量在一次爆发中释放出来。阿克蒙德被消灭了。]=],
		},
		{
			title = "意义",
			text = [=[这场胜利拯救了世界，但代价巨大。{link:nordrassil}诺达希尔{/link}交出了它的力量，{link:night-elves}暗夜精灵{/link}失去了它所赋予的永生。大树被烧焦了，却没有死去。这场战役也在{link:alliance}联盟{/link}与{link:horde}部落{/link}之间促成了一段短暂的和平。]=],
		},
	},
})

Translate("zhCN", "culling-of-stratholme", {
	title = "斯坦索姆的净化",
	sections = {
		{
			title = "概述",
			text = [=[斯坦索姆的净化是{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子的士兵对斯坦索姆居民的屠杀。它发生在{link:third-war}第三次战争{/link}中，当时亡灵瘟疫已蔓延到这座城市。它标志着王子堕落的开始。]=],
		},
		{
			title = "起源",
			text = [=[{link:arthas-menethil}阿尔萨斯{/link}与女术士{link:jaina-proudmoore}吉安娜·普罗德摩尔{/link}和他的导师{link:uther-the-lightbringer}光明使者乌瑟尔{/link}一起，在{link:lordaeron}洛丹伦{/link}各地追查瘟疫。他得知{link:cult-of-the-damned}诅咒教派{/link}污染了从{link:ruins-of-andorhal}安多哈尔{/link}粮仓运出的谷物。在斯坦索姆，他发现被污染的谷物已经分发了下去。每一个吃了它的人很快都会死去，并作为{link:scourge}天灾军团{/link}的一员重新站起来。]=],
		},
		{
			title = "历史",
			text = [=[{link:arthas-menethil}阿尔萨斯{/link}下令在居民变异之前清洗这座城市。{link:uther-the-lightbringer}乌瑟尔{/link}拒绝参与，阿尔萨斯以叛国罪解除了他的指挥权。{link:jaina-proudmoore}吉安娜{/link}不忍目睹，离开了他。王子率领仍然忠于他的士兵进入斯坦索姆，挨家挨户地将居民屠戮。在他们尚未赶到的地方，市民们已经开始变异。恐惧魔王玛尔加尼斯正在城中等候。他嘲弄王子，挑战他追到诺森德去。阿尔萨斯发誓要追杀他。]=],
		},
		{
			title = "意义",
			text = [=[这场净化斩断了{link:arthas-menethil}阿尔萨斯{/link}与那些爱他之人的纽带。它把他送往北方，送向霜之哀伤，送向{link:fall-of-lordaeron}洛丹伦的陷落{/link}。]=],
		},
		{
			title = "当今",
			text = [=[斯坦索姆的废墟位于{link:eastern-plaguelands}东瘟疫之地{/link}。{link:scourge}天灾军团{/link}占据着城市的大部分地区。{link:scarlet-crusade}血色十字军{/link}死守着其余部分，仍在与{link:arthas-menethil}阿尔萨斯{/link}的剑未能拯救的死者作战。]=],
		},
	},
})

Translate("zhCN", "fall-of-lordaeron", {
	title = "洛丹伦的陷落",
	sections = {
		{
			title = "概述",
			text = [=[洛丹伦的陷落是最伟大的{link:humans}人类{/link}王国被{link:scourge}天灾军团{/link}毁灭的事件。它发生在{link:third-war}第三次战争{/link}中，当时{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子作为巫妖王的仆从从诺森德归来。在所有曾领导{link:alliance}联盟{/link}的王国中，没有一个跌落得如此之深、如此之快。]=],
		},
		{
			title = "历史",
			text = [=[在诺森德，{link:arthas-menethil}阿尔萨斯{/link}拿起符文剑霜之哀伤，杀死了恐惧魔王玛尔加尼斯。他的灵魂也被那把剑夺走了。他航行回国，首都的人民把他当作英雄来迎接。他走进王座大厅，杀死了他的父亲，国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}。{link:scourge}天灾军团{/link}随之席卷了整个王国。阿尔萨斯杀死了{link:uther-the-lightbringer}光明使者乌瑟尔{/link}，夺走了装着他父亲骨灰的瓮，好用它来运送{link:kel-thuzad}克尔苏加德{/link}的遗骸。他进军{link:quel-thalas}奎尔萨拉斯{/link}，击溃了{link:sylvanas-windrunner}希尔瓦娜斯·风行者{/link}率领的守军，并在太阳之井的水中复活了克尔苏加德。不久之后，天灾军团帮助{link:archimonde}阿克蒙德{/link}在{link:dalaran}达拉然{/link}进入了世界。]=],
		},
		{
			title = "陷落之后",
			text = [=[{link:archimonde}阿克蒙德{/link}被消灭后，恐惧魔王们企图亲自统治这个破碎的王国。{link:arthas-menethil}阿尔萨斯{/link}在响应主人召他北上的呼唤之前，转而与他们反目。已成亡灵的{link:sylvanas-windrunner}希尔瓦娜斯{/link}挣脱了巫妖王的意志。她和她的{link:forsaken}被遗忘者{/link}推翻了恐惧魔王，占据了首都的废墟。]=],
		},
		{
			title = "当今",
			text = [=[{link:lordaeron}洛丹伦{/link}已不复存在。它的腹地成了瘟疫之地，被{link:scourge}天灾军团{/link}占据。{link:scarlet-crusade}血色十字军{/link}在{link:tirisfal-glades}提瑞斯法林地{/link}及更远的地方与死者作战。在破碎的王座大厅之下，{link:forsaken}被遗忘者{/link}建起了{link:undercity}幽暗城{/link}。]=],
		},
	},
})

Translate("zhCN", "dark-portal", {
	title = "黑暗之门",
	sections = {
		{
			title = "概述",
			text = [=[黑暗之门是连接{link:azeroth}艾泽拉斯{/link}与{link:orcs}兽人{/link}故乡德拉诺的巨大通道。它矗立在{link:blasted-lands}诅咒之地{/link}，那里曾是黑色{link:swamp-of-sorrows}沼泽{/link}的沼地。{link:horde}部落{/link}经由它而来，{link:first-war}第一次战争{/link}也随之开始。]=],
		},
		{
			title = "起源",
			text = [=[传送门是由来自德拉诺的术士{link:gul-dan}古尔丹{/link}和他的{link:shadow-council}暗影议会{/link}，在{link:azeroth}艾泽拉斯{/link}一方{link:medivh}麦迪文{/link}的帮助下打开的。麦迪文是{link:tirisfal-glades}提瑞斯法{/link}守护者，但他的心智早已被{link:burning-legion}燃烧军团{/link}之主{link:sargeras}萨格拉斯{/link}所控制。起初裂隙很窄，只有少数斥候穿过。后来它被扩大了，整个{link:horde}部落{/link}都越过它进入了{link:swamp-of-sorrows}沼泽{/link}。]=],
		},
		{
			title = "历史",
			text = [=[{link:horde}部落{/link}在传送门周围建起了一座巨大的堡垒，它成了部落输送援军的通道。{link:second-war}第二次战争{/link}失败后，{link:alliance}联盟{/link}摧毁了黑暗之门。几年后，萨满{link:ner-zhul}耐奥祖{/link}再次打开了它，率领一个新的部落穿过它来窃取强大的神器。联盟派出一支远征军越过传送门进入德拉诺，要从根源上消除威胁。耐奥祖撕开了通往其他世界的裂隙，传送门再次被摧毁。远征军没有回来。{link:azeroth}艾泽拉斯{/link}没有人知道它的下落。]=],
		},
		{
			title = "当今",
			text = [=[黑暗之门在{link:blasted-lands}诅咒之地{/link}的南端黯然无声地矗立着。{link:nethergarde-keep}守望堡{/link}的法师和士兵监视着它。恶魔仍在它周围的荒地上游荡。]=],
		},
	},
})

Translate("zhCN", "well-of-eternity", {
	title = "永恒之井",
	sections = {
		{
			title = "概述",
			text = [=[永恒之井是远古世界中心一座蕴含奥术力量的巨大湖泊。{link:night-elves}卡多雷{/link}帝国在它的岸边崛起。它的毁灭终结了{link:war-of-the-ancients}上古战争{/link}，并引发了{link:great-sundering}大分裂{/link}。]=],
		},
		{
			title = "本质",
			text = [=[最古老的史书说，永恒之井填满了大地上的一道伤口，那是泰坦与上古之神交战时留下的。它的水黑暗而深邃，蕴含着世界本身的原始力量。定居在它附近的{link:trolls}巨魔{/link}经过许多世代发生了变化，成为了{link:night-elves}暗夜精灵{/link}。他们学会了驾驭它的力量，他们对{link:arcane-magic}奥术魔法{/link}的精通使他们的帝国成为世界的奇迹。]=],
		},
		{
			title = "历史",
			text = [=[{link:night-elves}暗夜精灵{/link}女王{link:queen-azshara}艾萨拉{/link}在井畔建起了她的宫殿，她的上层精灵越来越深地汲取它的力量。他们的魔法引来了{link:burning-legion}燃烧军团{/link}。上层精灵试图在永恒之井内部为{link:sargeras}萨格拉斯{/link}打开一道传送门。传送门被瓦解时，永恒之井崩塌了，大陆被撕裂。在它原来所在的地方，大漩涡如今仍在肆虐。]=],
		},
		{
			title = "遗泽",
			text = [=[永恒之井有一部分留存了下来。{link:illidan-stormrage}伊利丹·怒风{/link}保存了几瓶井水，并把它们倒进了{link:mount-hyjal}海加尔山{/link}上的一座湖泊，造出了第二口永恒之井。守护巨龙在那里种下了{link:nordrassil}诺达希尔{/link}。被流放的上层精灵把另一瓶井水带到了东方。他们用它造出了太阳之井，即{link:quel-thalas}奎尔萨拉斯{/link}的力量之源。在{link:third-war}第三次战争{/link}中，{link:archimonde}阿克蒙德{/link}来到{link:kalimdor}卡利姆多{/link}，想要吞噬第二口永恒之井的力量，但他失败了。]=],
		},
	},
})

Translate("zhCN", "nordrassil", {
	title = "诺达希尔",
	sections = {
		{
			title = "概述",
			text = [=[诺达希尔是世界之树，耸立在{link:kalimdor}卡利姆多{/link}的{link:mount-hyjal}海加尔山{/link}顶。一万年来，它守护着第二口{link:well-of-eternity}永恒之井{/link}，并赋予{link:night-elves}暗夜精灵{/link}永生。它是{link:battle-of-mount-hyjal}海加尔山之战{/link}的中心。]=],
		},
		{
			title = "起源",
			text = [=[{link:great-sundering}大分裂{/link}之后，幸存的{link:night-elves}暗夜精灵{/link}发现{link:illidan-stormrage}伊利丹·怒风{/link}在{link:mount-hyjal}海加尔山{/link}顶造出了一口新的{link:well-of-eternity}永恒之井{/link}。守护巨龙来到他们身边。{link:alexstrasza}阿莱克丝塔萨{/link}把一颗神圣的种子放入新井的水中，一棵巨树从中长出，它的根汲饮着井水，并将它封存起来。诺兹多姆祝福了这棵树，让暗夜精灵只要它屹立不倒就能长生。伊瑟拉把它与{link:emerald-dream}翡翠梦境{/link}相连，好让德鲁伊能借由它行走于梦境之中。]=],
		},
		{
			title = "历史",
			text = [=[{link:night-elves}暗夜精灵{/link}在它的枝叶下进行着他们漫长的守望。{link:malfurion-stormrage}玛法里奥·怒风{/link}的德鲁伊们在它的荫蔽下沉睡，他们的灵魂在梦境中漫游。在{link:third-war}第三次战争{/link}中，{link:archimonde}阿克蒙德{/link}向大树进军，要汲干它下方的{link:well-of-eternity}永恒之井{/link}。当他攀上树干时，玛法里奥召唤了祖先的灵魂，诺达希尔的力量在消灭恶魔的过程中耗尽了。]=],
		},
		{
			title = "当今",
			text = [=[诺达希尔依然屹立，却伤痕累累，力量衰弱。{link:night-elves}暗夜精灵{/link}不再拥有永生。他们在北部海岸外种下了一棵新树{link:teldrassil}泰达希尔{/link}，但它是在没有守护巨龙祝福的情况下生长起来的。许多老德鲁伊怀疑它是否根本就不该被种下。]=],
		},
	},
})

Translate("zhCN", "holy-light", {
	title = "圣光",
	sections = {
		{
			title = "概述",
			text = [=[圣光是回应虔诚者的信仰与美德之力。它的牧师治愈伤口，抚慰心灵。它的圣骑士把它带上战场，作为对抗亡灵与恶魔的盾牌和武器。{link:eastern-kingdoms}东部王国{/link}的大多数{link:humans}人类{/link}都在它的信仰中长大，如今许多{link:dwarves}矮人{/link}也信奉它。]=],
		},
		{
			title = "本质",
			text = [=[信徒们并不教导说圣光是一位神。他们教导说，它存在于所有追求美德的人心中，并通过同情、勇气和牺牲变得更加强大。它无法被窃取，也无法被扭曲去行残暴之事。那些试图在没有信仰的情况下驾驭它的人会发现，它不会回应他们。]=],
		},
		{
			title = "历史",
			text = [=[圣光的信仰在{link:humans}人类{/link}中根基深厚，可以追溯到{link:arathor}阿拉索{/link}的时代。在{link:kingdom-of-stormwind}暴风王国{/link}，它由{link:northshire-abbey}北郡修道院{/link}和光明大教堂守护。{link:first-war}第一次战争{/link}之后，大主教{link:alonsus-faol}阿隆索斯·法奥{/link}看到，仅靠信仰并没有拯救南方。他把圣光的牧师与{link:lordaeron}洛丹伦{/link}最优秀的骑士结合起来，建立了白银之手骑士团，即最早的圣骑士。{link:uther-the-lightbringer}光明使者乌瑟尔{/link}是其中的第一人。圣骑士们在{link:second-war}第二次战争{/link}中光荣地战斗。在{link:third-war}第三次战争{/link}中，骑士团分崩离析。{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子也曾是其中一员。]=],
		},
		{
			title = "当今",
			text = [=[圣光仍是{link:stormwind-city}暴风城{/link}信仰的核心，它的牧师在每一座城镇服务。在{link:lordaeron}洛丹伦{/link}，它已成为一声战斗的呐喊。{link:scarlet-crusade}血色十字军{/link}以圣光之名烧死一切被怀疑染上瘟疫的人。{link:argent-dawn}银色黎明{/link}则以更沉稳的手与同样的死者作战。]=],
		},
	},
})

Translate("zhCN", "arcane-magic", {
	title = "奥术魔法",
	sections = {
		{
			title = "概述",
			text = [=[奥术魔法是心智与世界法则的魔法。它的大师能扭曲时空，召唤烈火与冰霜，看见他人看不见的东西。它是{link:azeroth}艾泽拉斯{/link}最古老的习得魔法，对那些过于热爱它的人来说，也是最危险的魔法。]=],
		},
		{
			title = "本质",
			text = [=[有天赋和自律的人可以学会奥术之力，但它不会白白给予任何东西。驾驭它的人会渐渐渴求它。它也会召唤{link:burning-legion}燃烧军团{/link}的恶魔，它们渴望着富含魔法的世界。{link:azeroth}艾泽拉斯{/link}每一个奥术力量的伟大时代，都曾引来燃烧军团的注视。]=],
		},
		{
			title = "历史",
			text = [=[{link:night-elves}暗夜精灵{/link}最早在{link:well-of-eternity}永恒之井{/link}掌握了奥术魔法，他们的上层精灵用它引发了{link:war-of-the-ancients}上古战争{/link}。{link:great-sundering}大分裂{/link}之后，暗夜精灵禁止了奥术魔法。那些不愿放弃它的上层精灵遭到放逐。他们在东方建立了{link:quel-thalas}奎尔萨拉斯{/link}，成为了{link:high-elves}高等精灵{/link}。在{link:troll-wars}巨魔战争{/link}中，他们把魔法传授给{link:arathor}阿拉索{/link}的一百名{link:humans}人类{/link}。这门技艺在人类的土地上传播开来。阿拉索的法师们建起了{link:dalaran}达拉然{/link}城，它的统治{link:shadow-council}议会{/link}{link:kirin-tor}肯瑞托{/link}监督着魔法的使用。当恶魔开始出现在人类的土地上时，精灵与法师们建立了秘密的{link:tirisfal-glades}提瑞斯法{/link}议会。他们选出一位守护者，独自与{link:burning-legion}燃烧军团{/link}作战。最后的守护者是{link:aegwynn}艾格文{/link}和她的儿子{link:medivh}麦迪文{/link}。]=],
		},
		{
			title = "当今",
			text = [=[{link:dalaran}达拉然{/link}在{link:third-war}第三次战争{/link}中被{link:archimonde}阿克蒙德{/link}摧毁。如今它的法师们在{link:alterac-mountains}奥特兰克{/link}山麓一道闪烁的紫色屏障后重建它。法师们仍在{link:stormwind-city}暴风城{/link}、{link:ironforge}铁炉堡{/link}和{link:theramore-isle}塞拉摩{/link}接受训练。在{link:night-elves}暗夜精灵{/link}中，禁止奥术魔法的古老法律依然有效。]=],
		},
	},
})

Translate("zhCN", "fel-magic", {
	title = "邪能魔法",
	sections = {
		{
			title = "概述",
			text = [=[邪能魔法是{link:burning-legion}燃烧军团{/link}的魔法。它从毁灭和对生命的掠夺中汲取力量。它燃烧着病态的绿色火焰，毒害土地，也毒害使用者的灵魂。术士们明知代价，仍在与它做交易。]=],
		},
		{
			title = "本质",
			text = [=[邪能之力来得快、力量强，几乎不需要研习。它要求的是吞噬某种东西：一条生命、一个灵魂、土地的健康。使用它的人会在身体和内心上慢慢改变。经常使用它的地方会枯萎腐烂。]=],
		},
		{
			title = "历史",
			text = [=[邪能魔法最早随{link:burning-legion}燃烧军团{/link}在{link:war-of-the-ancients}上古战争{/link}中来到{link:azeroth}艾泽拉斯{/link}。许多效忠于恶魔的上层精灵被扭曲成了{link:satyrs}萨特{/link}。一万年后，它又通过{link:orcs}兽人{/link}再次到来。在德拉诺，恶魔领主{link:kil-jaeden}基尔加丹{/link}把它的秘密传授给了{link:gul-dan}古尔丹{/link}和他的术士们。兽人酋长们饮下了恶魔{link:mannoroth}玛诺洛斯{/link}的血，它使他们充满了可怕的狂怒。德拉诺的大地在他们的魔法下死去。兽人把这个诅咒带过{link:dark-portal}黑暗之门{/link}，带进了{link:first-war}第一次战争{/link}和{link:second-war}第二次战争{/link}。在{link:third-war}第三次战争{/link}中，{link:grom-hellscream}格罗姆·地狱咆哮{/link}杀死了玛诺洛斯，以自己的生命为代价，把他的族人从恶魔之血中解放出来。{link:illidan-stormrage}伊利丹·怒风{/link}吞噬了{link:skull-of-gul-dan}古尔丹之颅{/link}，获得了恶魔的力量。]=],
		},
		{
			title = "当今",
			text = [=[{link:felwood}费伍德森林{/link}的森林仍带着{link:burning-legion}燃烧军团{/link}的污染。{link:burning-blade}火刃氏族{/link}的术士在{link:orgrimmar}奥格瑞玛{/link}和{link:durotar}杜隆塔尔{/link}的阴影中侍奉恶魔。{link:satyrs}萨特{/link}出没于{link:ashenvale}灰谷{/link}。{link:alliance}联盟{/link}和{link:horde}部落{/link}的术士仍在研习这门技艺。他们坚称自己是它的主人。]=],
		},
	},
})

Translate("zhCN", "emerald-dream", {
	title = "翡翠梦境",
	sections = {
		{
			title = "概述",
			text = [=[翡翠梦境是一个映照着世界的广阔灵界。它展现的是{link:azeroth}艾泽拉斯{/link}可能有的模样，原始而未被凡人之手触碰。它的守护者是绿龙军团的守护巨龙伊瑟拉。{link:night-elves}暗夜精灵{/link}的德鲁伊在身体沉睡时以灵魂行走于其中。]=],
		},
		{
			title = "本质",
			text = [=[史书认为，泰坦把梦境塑造成他们为世界所做设计的一幅活的图景。它是生长与梦的国度。绿龙守卫着它的大门，荒野之灵居住其中。那里的时间和距离不遵循清醒世界的规则。]=],
		},
		{
			title = "历史",
			text = [=[半神{link:cenarius}塞纳留斯{/link}把德鲁伊之道传授给{link:malfurion-stormrage}玛法里奥·怒风{/link}，玛法里奥借此学会了进入梦境。{link:war-of-the-ancients}上古战争{/link}之后，伊瑟拉把{link:nordrassil}诺达希尔{/link}与梦境相连。数千年来，{link:cenarion-circle}塞纳里奥议会{/link}的德鲁伊在隐秘的兽穴中沉睡，他们的灵魂在梦境中漫游，而{link:sentinels}哨兵{/link}们守护着他们的身体。他们被唤醒，投身于{link:third-war}第三次战争{/link}。胜利之后，德鲁伊们回到了他们的工作中。]=],
		},
		{
			title = "当今",
			text = [=[{link:malfurion-stormrage}玛法里奥{/link}再一次进入了梦境，至今没有回来。{link:fandral-staghelm}范达尔·鹿盔{/link}在他不在时领导德鲁伊。梦境中出了问题。有人在清醒世界中看到绿龙，其中一些已不再是原来的样子。{link:moonglade}月光林地{/link}的德鲁伊说起一股正在梦境中蔓延的黑暗，至今无人能说出它的名字。]=],
		},
	},
})

Translate("zhCN", "elements", {
	title = "元素",
	sections = {
		{
			title = "概述",
			text = [=[元素是大地、火焰、水和空气的活的力量。它们原始的形态狂野而具有破坏性。在平衡之中，它们维系着世界。{link:orcs}兽人{/link}、{link:tauren}牛头人{/link}和{link:trolls}巨魔{/link}的萨满与元素之灵交谈，请求它们的帮助。]=],
		},
		{
			title = "本质",
			text = [=[四位伟大的元素领主统治着元素。{link:ragnar-thunderbrew}拉格纳{/link}罗斯是火焰之王。塞拉赞恩是岩石之母。{link:al-akir}奥拉基尔{/link}是风之王，他的国度是{link:skywall}天空之墙{/link}。耐普图隆是潮汐之王。他们的仆从狂野，敌视凡人的生命。然而，较弱的元素之灵是可以讲道理的。萨满并不命令它们。萨满只是请求，由元素之灵选择是否回应。]=],
		},
		{
			title = "历史",
			text = [=[在世界的最初纪元，元素领主为上古之神而战。泰坦击败了他们，把他们束缚在一个与世界隔绝的国度中。在德拉诺，{link:orcs}兽人{/link}曾是一个萨满的民族。当{link:gul-dan}古尔丹{/link}使他们转向恶魔魔法时，元素之灵抛弃了他们。很久以后，在卡兹莫丹，{link:dark-iron-dwarves}黑铁{/link}领主{link:ruins-of-thaurissan}索瑞森{/link}把{link:ragnar-thunderbrew}拉格纳{/link}罗斯召唤到了世界上。这次召唤杀死了这位领主，并造就了{link:blackrock-mountain}黑石山{/link}。拉格纳罗斯从此便一直住在山下。{link:second-war}第二次战争{/link}之后，老萨满{link:drek-thar}德雷克塔尔{/link}把元素之灵的道路传授给了年轻的{link:thrall}萨尔{/link}。元素回应了新的{link:horde}部落{/link}，而它们从未这样回应过旧部落。]=],
		},
		{
			title = "当今",
			text = [=[{link:ragnar-thunderbrew}拉格纳{/link}罗斯从{link:blackrock-mountain}黑石山{/link}熔岩翻滚的深处统治着{link:dark-iron-dwarves}黑铁矮人{/link}。{link:twilight-s-hammer}暮光之锤{/link}企图为了自己的目的唤醒元素。{link:horde}部落{/link}的萨满维护着古老的平衡，就像他们的祖先在恶魔到来之前所做的那样。]=],
		},
	},
})
